"""specs_s200032.py - Sonnet-w2 family I (generated by mkfamI.py). 0x41e290 returns a heap object or 0; BASE, GUARD and the slots record the SEH chain; c_in points to an object whose
unaligned dword at +0x15 is X, an object whose slot 0x40 stub writes a random value through its out pointer (recorded only as null/non-null); the engine table slot 0x58 stub gets that value.
The guard global is zero about half the time. Fake outer SEH records 0-2; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _mk(base, glob, guard):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        p = r.choice([0, rnd(c, 0x80), rnd(c, 0x80), rnd(c, 0x80)])
        hook_rec(c, 0x41e290, 1, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, base, 2, ret=r.getrandbits(32), pop=8, this=True, side=seh_record(c, 2))
        hook_rec(c, guard, 0, ret=r.getrandbits(32), this=True, side=seh_record(c, 2))
        c.emu.w32(glob, r.choice([0, 0, 1, r.getrandbits(32)]))
        sr = seh_record(c, 2)

        def outw(emu, k):
            emu.w32(emu.arg32(0), r.getrandbits(32))
            sr(emu, k)
        xo = obj(c, 0x20, {0x40: pystub(c, 1, ret=r.getrandbits(32), this=True, nullflag=(0,), side=outw)}, nslots=0x20)
        cin = rnd(c, 0x40)
        c.emu.wbytes(cin + 0x15, xo.to_bytes(4, 'little'))
        eng = rnd(c, 0x1b00)
        c.emu.w32(0x70039c, eng)
        tb = obj(c, 0x40, {0x58: pystub(c, 1, ret=r.getrandbits(32), this=True, side=seh_record(c, 2))}, nslots=0x30)
        c.emu.w32(eng + 0x9b, tb)
        return [cin, r.getrandbits(32)]
    return gen


S(0x504660, 'GUESS famI 0x504660', 'fastcall', None, ret='eax', gen=_mk(0x5f9700, 0x700e70, 0x5044c0), note='batch200032')
